import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { config } from '../config/index.js';
import { prisma } from '../config/db.js';

export interface AuthenticatedRequest extends Request {
  user?: {
    id: string;
    email: string;
    name: string;
    role: string;
  };
  guestId?: string;
}

/** Guest ids are generated by the browser; accept only sane, URL-safe values. */
const GUEST_ID_PATTERN = /^[A-Za-z0-9_-]{6,100}$/;

export function sanitizeGuestId(value: unknown): string | undefined {
  return typeof value === 'string' && GUEST_ID_PATTERN.test(value) ? value : undefined;
}

/** Resolves who is making the request: a signed-in user or an anonymous guest. */
export function getIdentity(req: AuthenticatedRequest): { userId?: string; guestId?: string } {
  return {
    userId: req.user?.id,
    guestId: req.guestId ?? sanitizeGuestId(req.headers['x-guest-id']),
  };
}

async function loadUserFromToken(token: string) {
  const decoded = jwt.verify(token, config.jwtSecret) as { id: string };
  return prisma.user.findUnique({
    where: { id: decoded.id },
    select: { id: true, email: true, name: true, role: true },
  });
}

export async function requireAuth(req: AuthenticatedRequest, res: Response, next: NextFunction) {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({
        success: false,
        error: 'Unauthorized: Authentication token is required.',
      });
    }

    const user = await loadUserFromToken(authHeader.split(' ')[1]);
    if (!user) {
      return res.status(401).json({
        success: false,
        error: 'Unauthorized: User account not found.',
      });
    }

    req.user = user;
    req.guestId = sanitizeGuestId(req.headers['x-guest-id']);
    next();
  } catch (err: any) {
    // jwt errors are auth failures; anything else (e.g. database down) is a server error.
    if (err?.name === 'JsonWebTokenError' || err?.name === 'TokenExpiredError' || err?.name === 'NotBeforeError') {
      return res.status(401).json({
        success: false,
        error: 'Unauthorized: Invalid or expired token.',
      });
    }
    next(err);
  }
}

/**
 * Identifies the caller as a user (valid Bearer token) or guest (x-guest-id header).
 * A token that is present but invalid/expired is rejected with 401 rather than silently
 * downgraded to a guest, so clients can detect it and ask the user to sign in again.
 */
export function requireAdmin(req: AuthenticatedRequest, res: Response, next: NextFunction) {
  if (!req.user) {
    return res.status(401).json({
      success: false,
      error: 'Unauthorized: Authentication token is required.',
    });
  }

  if (req.user.role !== 'ADMIN') {
    return res.status(403).json({
      success: false,
      error: 'Forbidden: Administrator access is required.',
    });
  }

  next();
}

export async function optionalAuth(req: AuthenticatedRequest, res: Response, next: NextFunction) {
  try {
    req.guestId = sanitizeGuestId(req.headers['x-guest-id']);

    const authHeader = req.headers.authorization;
    if (authHeader && authHeader.startsWith('Bearer ')) {
      const user = await loadUserFromToken(authHeader.split(' ')[1]);
      if (!user) {
        return res.status(401).json({
          success: false,
          error: 'Unauthorized: User account not found.',
        });
      }
      req.user = user;
    }

    next();
  } catch (err: any) {
    if (err?.name === 'JsonWebTokenError' || err?.name === 'TokenExpiredError' || err?.name === 'NotBeforeError') {
      return res.status(401).json({
        success: false,
        error: 'Unauthorized: Invalid or expired token.',
      });
    }
    next(err);
  }
}
